﻿using OpenTK.Mathematics;

namespace ArcEngine.Engine.Core;

public class Transform
{
    public Vector3 Position = Vector3.Zero;
    public Vector3 Rotation = Vector3.Zero;
    public Vector3 Scale = Vector3.One;

    public Matrix4 GetModelMatrix()
    {
        Matrix4 translation = Matrix4.CreateTranslation(Position);
        Matrix4 rotationX = Matrix4.CreateRotationX(MathHelper.DegreesToRadians(Rotation.X));
        Matrix4 rotationY = Matrix4.CreateRotationY(MathHelper.DegreesToRadians(Rotation.Y));
        Matrix4 rotationZ = Matrix4.CreateRotationZ(MathHelper.DegreesToRadians(Rotation.Z));
        Matrix4 scale = Matrix4.CreateScale(Scale);

        return scale * rotationZ * rotationY * rotationX * translation;
    }
}

﻿using OpenTK.Graphics.OpenGL4;
using OpenTK.Mathematics;

namespace ArcEngine.Engine.Rendering;

public class Material
{
    public Shader Shader;
    public Texture Texture;

    public Vector3 Color = new Vector3(1f, 1f, 1f);

    public Material(Shader shader)
    {
        Shader = shader;
    }

    public void Apply()
    {
        Shader.Use();

        Shader.SetVector3("materialColor", Color);

        if (Texture != null)
        {
            GL.ActiveTexture(TextureUnit.Texture0);
            Texture.Use();
            Shader.SetInt("texture0", 0);
        }
    }
}

﻿using OpenTK.Graphics.OpenGL4;
using OpenTK.Mathematics;
using System.Collections.Generic;
using System.IO;

namespace ArcEngine.Engine.Rendering;

public class Shader
{
    public int Handle;
    private Dictionary<string, int> _uniformLocations = new();

    public Shader(string vertexPath, string fragmentPath)
    {
        string vertexSource = File.ReadAllText(vertexPath);
        string fragmentSource = File.ReadAllText(fragmentPath);

        int vertexShader = GL.CreateShader(ShaderType.VertexShader);
        GL.ShaderSource(vertexShader, vertexSource);
        GL.CompileShader(vertexShader);

        int fragmentShader = GL.CreateShader(ShaderType.FragmentShader);
        GL.ShaderSource(fragmentShader, fragmentSource);
        GL.CompileShader(fragmentShader);

        Handle = GL.CreateProgram();
        GL.AttachShader(Handle, vertexShader);
        GL.AttachShader(Handle, fragmentShader);
        GL.LinkProgram(Handle);

        GL.DeleteShader(vertexShader);
        GL.DeleteShader(fragmentShader);

        // Cache uniforms
        GL.GetProgram(Handle, GetProgramParameterName.ActiveUniforms, out int count);

        for (int i = 0; i < count; i++)
        {
            var key = GL.GetActiveUniform(Handle, i, out _, out _);
            var location = GL.GetUniformLocation(Handle, key);
            _uniformLocations[key] = location;
        }
    }

    public void Use()
    {
        GL.UseProgram(Handle);
    }
    public void SetInt(string name, int value)
    {
        if (_uniformLocations.TryGetValue(name, out int location))
        {
            GL.Uniform1(location, value);
        }
    }

    public void SetMatrix4(string name, Matrix4 value)
    {
        if (_uniformLocations.TryGetValue(name, out int location))
        {
            GL.UniformMatrix4(location, false, ref value);
        }
    }

    public void SetVector3(string name, Vector3 value)
    {
        if (_uniformLocations.TryGetValue(name, out int location))
        {
            GL.Uniform3(location, value);
        }
    }
}

﻿using OpenTK.Graphics.OpenGL4;
using ArcEngine.Engine.Core;

namespace ArcEngine.Engine.Rendering;

public class Renderer
{
    public void Init()
    {
        GL.Enable(EnableCap.DepthTest);
    }

    public void Clear()
    {
        GL.ClearColor(0.2f, 0.3f, 0.4f, 1.0f);
        GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);
    }

    public void RenderObject(GameObject obj, Camera camera, float aspectRatio)
    {
        if (obj.Mesh == null || obj.Material == null)
            return;

        obj.Material.Apply();

        var model = obj.Transform.GetModelMatrix();
        var view = camera.GetViewMatrix();
        var projection = camera.GetProjectionMatrix(aspectRatio);

        obj.Material.Shader.SetMatrix4("model", model);
        obj.Material.Shader.SetMatrix4("view", view);
        obj.Material.Shader.SetMatrix4("projection", projection);

        obj.Material.Shader.SetVector3("lightPos", new OpenTK.Mathematics.Vector3(2f, 2f, 2f));
        obj.Material.Shader.SetVector3("lightColor", new OpenTK.Mathematics.Vector3(1f, 1f, 1f));

        obj.Mesh.Draw();
    }
}

﻿using OpenTK.Graphics.OpenGL4;
using StbImageSharp;

namespace ArcEngine.Engine.Rendering;

public class Texture
{
    public int Handle;

    public Texture(string path)
    {
        Handle = GL.GenTexture();
        GL.BindTexture(TextureTarget.Texture2D, Handle);

        // Load image using StbImageSharp
        using (var stream = File.OpenRead(path))
        {
            var image = ImageResult.FromStream(stream, ColorComponents.RedGreenBlueAlpha);

            GL.TexImage2D(TextureTarget.Texture2D,
                0,
                PixelInternalFormat.Rgba,
                image.Width,
                image.Height,
                0,
                PixelFormat.Rgba,
                PixelType.UnsignedByte,
                image.Data);
        }

        // Texture settings
        GL.TexParameter(TextureTarget.Texture2D, TextureParameterName.TextureMinFilter, (int)TextureMinFilter.Linear);
        GL.TexParameter(TextureTarget.Texture2D, TextureParameterName.TextureMagFilter, (int)TextureMagFilter.Linear);

        GL.TexParameter(TextureTarget.Texture2D, TextureParameterName.TextureWrapS, (int)TextureWrapMode.Repeat);
        GL.TexParameter(TextureTarget.Texture2D, TextureParameterName.TextureWrapT, (int)TextureWrapMode.Repeat);

        GL.GenerateMipmap(GenerateMipmapTarget.Texture2D);
    }

    public void Use()
    {
        GL.BindTexture(TextureTarget.Texture2D, Handle);
    }
}

﻿using OpenTK.Graphics.OpenGL4;

namespace ArcEngine.Engine.Rendering;

public class Mesh
{
    private int _vao;
    private int _vbo;
    private int _vertexCount;

    public Mesh(float[] vertices)
    {
        _vertexCount = vertices.Length / 3;

        _vao = GL.GenVertexArray();
        _vbo = GL.GenBuffer();

        GL.BindVertexArray(_vao);

        GL.BindBuffer(BufferTarget.ArrayBuffer, _vbo);
        GL.BufferData(BufferTarget.ArrayBuffer, vertices.Length * sizeof(float), vertices, BufferUsageHint.StaticDraw);

        // Position
        GL.VertexAttribPointer(0, 3, VertexAttribPointerType.Float, false, 8 * sizeof(float), 0);
        GL.EnableVertexAttribArray(0);

        // Normal
        GL.VertexAttribPointer(2, 3, VertexAttribPointerType.Float, false, 8 * sizeof(float), 3 * sizeof(float));
        GL.EnableVertexAttribArray(2);

        // UV
        GL.VertexAttribPointer(3, 2, VertexAttribPointerType.Float, false, 8 * sizeof(float), 6 * sizeof(float));
        GL.EnableVertexAttribArray(3);

        GL.BindVertexArray(0);
    }

    public void Draw()
    {
        GL.BindVertexArray(_vao);
        GL.DrawArrays(PrimitiveType.Triangles, 0, _vertexCount);
    }
}

#version 330 core

in vec3 normal;
in vec3 fragPos;
in vec2 uv;

out vec4 FragColor;

uniform vec3 lightPos;
uniform vec3 lightColor;
uniform sampler2D texture0;
uniform vec3 materialColor;

void main()
{
    vec3 texColor = texture(texture0, uv).rgb;

    vec3 norm = normalize(normal);
    vec3 lightDir = normalize(lightPos - fragPos);

    float diff = max(dot(norm, lightDir), 0.0);
    vec3 diffuse = diff * lightColor;

    vec3 result = diffuse * texColor * materialColor;

    FragColor = vec4(result, 1.0);
}

#version 330 core

layout (location = 0) in vec3 aPosition;
layout (location = 2) in vec3 aNormal;
layout (location = 3) in vec2 aUV;

out vec3 normal;
out vec3 fragPos;
out vec2 uv;

uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

void main()
{
    fragPos = vec3(model * vec4(aPosition, 1.0));
    normal = mat3(transpose(inverse(model))) * aNormal;
    uv = aUV;

    gl_Position = projection * view * vec4(fragPos, 1.0);
}

