﻿using OpenTK.Windowing.Desktop;
using OpenTK.Windowing.Common;

using ArcEngine.Engine.Input;
using ArcEngine.Engine.Loaders;
using ArcEngine.Engine.Rendering;

namespace ArcEngine.Engine.Core;

public class Game : GameWindow
{
    private Renderer _renderer;
    private Scene _scene;
    private InputManager _input;

    private GameObject _model;
    private Camera _camera;

    public Game(GameWindowSettings gws, NativeWindowSettings nws)
        : base(gws, nws)
    {
    }

    protected override void OnLoad()
    {
        base.OnLoad();

        InputManager.LockCursor(this);

        _renderer = new Renderer();
        _renderer.Init();

        _scene = new Scene();
        _camera = new Camera();
        _input = new InputManager();

        var shader = new Shader(
            "Assets/Shaders/basic.vert",
            "Assets/Shaders/basic.frag"
        );

        // Load a real OBJ model from disk and build a GameObject hierarchy from it.
        var data = ObjLoader.Load("Assets/Models/cube.obj");
        _model = ModelBuilder.Build(data, shader);
        _scene.Add(_model);
    }

    protected override void OnUpdateFrame(FrameEventArgs args)
    {
        base.OnUpdateFrame(args);

        float deltaTime = (float)args.Time;

        _input.Update(KeyboardState, MouseState);
        _camera.Update(_input, deltaTime);

        // Slowly spin the loaded model to show off lighting + normals.
        _model.Transform.Rotation.Y += 30f * deltaTime;
    }

    protected override void OnRenderFrame(FrameEventArgs args)
    {
        base.OnRenderFrame(args);

        _renderer.Clear();

        float aspectRatio = Size.X / (float)Size.Y;

        foreach (var obj in _scene.GetObjects())
        {
            _renderer.RenderObject(obj, _camera, aspectRatio);
        }

        SwapBuffers();
    }
}

