﻿using ImGuiNET;

using OpenTK.Mathematics;

using ArcEngine.Engine.Core;

using SnVec2 = System.Numerics.Vector2;
using SnVec3 = System.Numerics.Vector3;

namespace ArcEngine.Engine.Editor;

/// <summary>
/// Issues all per-frame ImGui calls for the editor: a Hierarchy window on the left,
/// an Inspector window on the right, and a small status / mode label in the corner.
/// All windows are read-only this sprint — editing arrives in 10b.
/// </summary>
public static class EditorUI
{
    private const float HierarchyWidth = 280f;
    private const float InspectorWidth = 340f;
    private const float StatusHeight = 32f;

    public static void Render(Scene scene)
    {
        DrawHierarchy(scene);
        DrawInspector();
        DrawStatusBar();
    }

    // ------------------------------------------------------------------------
    // Hierarchy
    // ------------------------------------------------------------------------

    private static void DrawHierarchy(Scene scene)
    {
        var io = ImGui.GetIO();
        ImGui.SetNextWindowPos(new SnVec2(0f, 0f), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(HierarchyWidth, io.DisplaySize.Y), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoMove | ImGuiWindowFlags.NoResize;
        if (!ImGui.Begin("Hierarchy", flags))
        {
            ImGui.End();
            return;
        }

        ImGui.Text($"GameObjects ({scene.GetObjects().Count})");
        ImGui.Separator();

        var objects = scene.GetObjects();
        for (int i = 0; i < objects.Count; i++)
        {
            var go = objects[i];
            bool isSelected = Selection.IsSelected(go);

            // Use ##i to disambiguate Selectable IDs when names collide.
            if (ImGui.Selectable($"{go.Name}##{i}", isSelected))
            {
                if (io.KeyShift) Selection.SelectRange(go, objects);
                else if (io.KeyCtrl) Selection.Toggle(go);
                else Selection.Set(go);
            }
        }

        ImGui.End();
    }

    // ------------------------------------------------------------------------
    // Inspector
    // ------------------------------------------------------------------------

    private static void DrawInspector()
    {
        var io = ImGui.GetIO();
        ImGui.SetNextWindowPos(new SnVec2(io.DisplaySize.X - InspectorWidth, 0f), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(InspectorWidth, io.DisplaySize.Y), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoMove | ImGuiWindowFlags.NoResize;
        if (!ImGui.Begin("Inspector", flags))
        {
            ImGui.End();
            return;
        }

        var sel = Selection.Selected;
        if (sel.Count == 0)
        {
            ImGui.TextDisabled("Nothing selected.");
            ImGui.End();
            return;
        }

        if (sel.Count > 1)
        {
            ImGui.Text($"Multiple selected ({sel.Count})");
            ImGui.Separator();
            foreach (var go in sel) ImGui.BulletText(go.Name);
            ImGui.End();
            return;
        }

        // Single-selection details.
        var target = sel[0];
        ImGui.Text(target.Name);
        ImGui.Separator();

        // Transform (read-only).
        if (ImGui.CollapsingHeader("Transform", ImGuiTreeNodeFlags.DefaultOpen))
        {
            ImGui.BeginDisabled();
            var pos = ToSn(target.Transform.Position);
            ImGui.DragFloat3("Position", ref pos);
            var rot = ToSn(target.Transform.Rotation);
            ImGui.DragFloat3("Rotation", ref rot);
            var scl = ToSn(target.Transform.Scale);
            ImGui.DragFloat3("Scale", ref scl);
            ImGui.EndDisabled();
        }

        // Components list.
        if (ImGui.CollapsingHeader("Components", ImGuiTreeNodeFlags.DefaultOpen))
        {
            int idx = 0;
            foreach (var c in target.Components)
            {
                ImGui.BulletText(c.GetType().Name);
                idx++;
            }
            if (idx == 0) ImGui.TextDisabled("(none)");
        }

        ImGui.End();
    }

    // ------------------------------------------------------------------------
    // Status bar — small mode indicator pinned to top-center.
    // ------------------------------------------------------------------------

    private static void DrawStatusBar()
    {
        var io = ImGui.GetIO();
        const float w = 220f;
        ImGui.SetNextWindowPos(new SnVec2((io.DisplaySize.X - w) * 0.5f, 8f), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(w, StatusHeight), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoTitleBar
                  | ImGuiWindowFlags.NoResize
                  | ImGuiWindowFlags.NoMove
                  | ImGuiWindowFlags.NoScrollbar
                  | ImGuiWindowFlags.NoSavedSettings
                  | ImGuiWindowFlags.NoBringToFrontOnFocus
                  | ImGuiWindowFlags.NoFocusOnAppearing;

        ImGui.SetNextWindowBgAlpha(0.6f);
        if (ImGui.Begin("##status", flags))
        {
            string mode = EditorState.IsPlayMode ? "PLAY" : "EDIT";
            ImGui.Text($"Mode: {mode}    [F1 to toggle]");
        }
        ImGui.End();
    }

    // ------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------

    private static SnVec3 ToSn(Vector3 v) => new(v.X, v.Y, v.Z);
}

