var cmd = asm.GetType("Hexa.NET.ImGui.ImDrawCmdPtr");
Console.WriteLine("\nImDrawCmdPtr.TextureId:");
foreach (var m in cmd.GetMembers().Where(x => x.Name.Contains("Tex"))) Console.WriteLine($"  [{m.MemberType}] {m.Name}");
