﻿using Hexa.NET.ImGui;

using OpenTK.Mathematics;

using ArcEngine.Engine.Core;
using ArcEngine.Engine.Lighting;
using ArcEngine.Engine.Physics;
using ArcEngine.Engine.Rendering;

using SnVec3 = System.Numerics.Vector3;
using SnVec4 = System.Numerics.Vector4;

namespace ArcEngine.Engine.Editor;

/// <summary>
/// Per-component editor renderers, dispatched by runtime type. Keeps the editor's
/// concerns out of the engine runtime: components themselves don't know about ImGui.
/// </summary>
public static class ComponentInspector
{
    public static void Draw(Component c)
    {
        switch (c)
        {
            case Transform t:           DrawTransform(t); break;
            case MeshRenderer mr:       DrawMeshRenderer(mr); break;
            case Camera cam:            DrawCamera(cam); break;
            case DirectionalLight dl:   DrawDirectionalLight(dl); break;
            case PointLight pl:         DrawPointLight(pl); break;
            case Rigidbody rb:          DrawRigidbody(rb); break;
            case BoxCollider bc:        DrawBoxCollider(bc); break;
            case SphereCollider sc:     DrawSphereCollider(sc); break;
            case Script:                ImGui.TextDisabled("(custom script — no fields exposed yet)"); break;
            default:                    ImGui.TextDisabled("(no editor for this component)"); break;
        }
    }

    // ------------------------------------------------------------------------
    // Transform
    // ------------------------------------------------------------------------

    private static void DrawTransform(Transform t)
    {
        var pos = ToSn(t.Position);
        if (ImGui.DragFloat3("Position", ref pos, 0.05f))
            t.Position = ToOtk(pos);

        var rot = ToSn(t.Rotation);
        if (ImGui.DragFloat3("Rotation", ref rot, 1.0f))
            t.Rotation = ToOtk(rot);

        var scl = ToSn(t.Scale);
        if (ImGui.DragFloat3("Scale", ref scl, 0.05f, 0.001f, 1000f))
            t.Scale = ToOtk(scl);
    }

    // ------------------------------------------------------------------------
    // MeshRenderer / Material
    // ------------------------------------------------------------------------

    private static void DrawMeshRenderer(MeshRenderer mr)
    {
        ImGui.TextDisabled($"Mesh: {(mr.Mesh != null ? "<set>" : "<null>")}");
        ImGui.TextDisabled($"Material: {(mr.Material != null ? "<set>" : "<null>")}");

        if (mr.Material != null)
        {
            ImGui.Separator();
            ImGui.Text("Material");

            var col = ToSn(mr.Material.Color);
            if (ImGui.ColorEdit3("Color", ref col))
                mr.Material.Color = ToOtk(col);

            float shin = mr.Material.Shininess;
            if (ImGui.DragFloat("Shininess", ref shin, 0.5f, 1f, 256f))
                mr.Material.Shininess = shin;
        }
    }

    // ------------------------------------------------------------------------
    // Camera
    // ------------------------------------------------------------------------

    private static void DrawCamera(Camera cam)
    {
        ImGui.BeginDisabled();
        float yaw = cam.Yaw;
        ImGui.DragFloat("Yaw", ref yaw);
        float pitch = cam.Pitch;
        ImGui.DragFloat("Pitch", ref pitch);
        ImGui.EndDisabled();
        ImGui.TextDisabled("(yaw/pitch driven by FpsCameraController)");

        float fov = cam.Fov;
        if (ImGui.DragFloat("FOV", ref fov, 0.5f, 10f, 120f))
            cam.Fov = fov;

        float nearZ = cam.NearClip;
        if (ImGui.DragFloat("Near", ref nearZ, 0.01f, 0.001f, cam.FarClip - 0.01f))
            cam.NearClip = nearZ;

        float farZ = cam.FarClip;
        if (ImGui.DragFloat("Far", ref farZ, 1f, cam.NearClip + 0.01f, 10000f))
            cam.FarClip = farZ;
    }

    // ------------------------------------------------------------------------
    // Lights
    // ------------------------------------------------------------------------

    private static void DrawDirectionalLight(DirectionalLight dl)
    {
        var dir = ToSn(dl.Direction);
        if (ImGui.DragFloat3("Direction", ref dir, 0.01f, -1f, 1f))
        {
            // Renormalize so any tiny drag still produces a unit vector.
            var v = ToOtk(dir);
            if (v.LengthSquared > 1e-6f) dl.Direction = Vector3.Normalize(v);
        }

        var color = ToSn(dl.Color);
        if (ImGui.ColorEdit3("Color", ref color))
            dl.Color = ToOtk(color);

        float intensity = dl.Intensity;
        if (ImGui.DragFloat("Intensity", ref intensity, 0.05f, 0f, 10f))
            dl.Intensity = intensity;

        bool castsShadows = dl.CastsShadows;
        if (ImGui.Checkbox("Casts Shadows", ref castsShadows))
            dl.CastsShadows = castsShadows;
    }

    private static void DrawPointLight(PointLight pl)
    {
        ImGui.TextDisabled("(position is driven by Transform)");

        var color = ToSn(pl.Color);
        if (ImGui.ColorEdit3("Color", ref color))
            pl.Color = ToOtk(color);

        float intensity = pl.Intensity;
        if (ImGui.DragFloat("Intensity", ref intensity, 0.05f, 0f, 10f))
            pl.Intensity = intensity;

        float c = pl.Constant;
        if (ImGui.DragFloat("Constant",  ref c, 0.01f, 0f, 10f)) pl.Constant = c;
        float lin = pl.Linear;
        if (ImGui.DragFloat("Linear",    ref lin, 0.01f, 0f, 10f)) pl.Linear = lin;
        float quad = pl.Quadratic;
        if (ImGui.DragFloat("Quadratic", ref quad, 0.001f, 0f, 10f)) pl.Quadratic = quad;
    }

    // ------------------------------------------------------------------------
    // Physics
    // ------------------------------------------------------------------------

    private static void DrawRigidbody(Rigidbody rb)
    {
        float mass = rb.Mass;
        if (ImGui.DragFloat("Mass", ref mass, 0.1f, 0.001f, 10000f))
            rb.Mass = mass;

        bool isStatic = rb.IsStatic;
        if (ImGui.Checkbox("Static", ref isStatic))
            rb.IsStatic = isStatic;

        ImGui.TextDisabled("(changes after Awake won't update the live body)");
    }

    private static void DrawBoxCollider(BoxCollider bc)
    {
        var size = ToSn(bc.Size);
        if (ImGui.DragFloat3("Size", ref size, 0.05f, 0.001f, 1000f))
            bc.Size = ToOtk(size);
        ImGui.TextDisabled("(changes after Awake won't update the live body)");
    }

    private static void DrawSphereCollider(SphereCollider sc)
    {
        float r = sc.Radius;
        if (ImGui.DragFloat("Radius", ref r, 0.05f, 0.001f, 1000f))
            sc.Radius = r;
        ImGui.TextDisabled("(changes after Awake won't update the live body)");
    }

    // ------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------

    private static SnVec3 ToSn(Vector3 v) => new(v.X, v.Y, v.Z);
    private static Vector3 ToOtk(SnVec3 v) => new(v.X, v.Y, v.Z);
}

﻿namespace ArcEngine.Engine.Editor;

public enum GizmoMode
{
    Translate,
    Rotate,
    Scale,
}

public enum GizmoSpace
{
    World,
    Local,
}

/// <summary>
/// Global editor toggle state. The engine starts in Edit mode (cursor visible,
/// FPS controller disabled, ImGui interactive). F1 flips to Play mode (cursor
/// grabbed, FPS controller active, ImGui visible-but-non-interactive).
/// </summary>
public static class EditorState
{
    private static bool s_isPlayMode;

    /// <summary>Fired when <see cref="IsPlayMode"/> changes value.</summary>
    public static event Action<bool>? PlayModeChanged;

    public static bool IsPlayMode
    {
        get => s_isPlayMode;
        set
        {
            if (s_isPlayMode == value) return;
            s_isPlayMode = value;
            PlayModeChanged?.Invoke(value);
        }
    }

    /// <summary>Active gizmo operation. Hotkeys: W = Translate, E = Rotate, R = Scale.</summary>
    public static GizmoMode GizmoMode { get; set; } = GizmoMode.Translate;

    /// <summary>World vs Local space for the gizmo. Hotkey: G to toggle.</summary>
    public static GizmoSpace GizmoSpace { get; set; } = GizmoSpace.World;
}

﻿using System.Linq;
using System.Reflection;

using Hexa.NET.ImGui;
using Hexa.NET.ImGuizmo;

using OpenTK.Mathematics;

using ArcEngine.Engine.Core;

using SnVec2 = System.Numerics.Vector2;
using SnVec3 = System.Numerics.Vector3;

namespace ArcEngine.Engine.Editor;

/// <summary>
/// Issues all per-frame ImGui calls for the editor: a Hierarchy window on the left,
/// an Inspector window (editable) on the right, a gizmo-mode toolbar, the 3D
/// translate/rotate/scale gizmo (ImGuizmo) over the viewport, and a status bar.
/// </summary>
public static class EditorUI
{
    private const float HierarchyWidth = 280f;
    private const float InspectorWidth = 340f;
    private const float ToolbarHeight = 40f;
    private const float StatusHeight = 32f;

    /// <summary>
    /// All Component subclasses we can let the user "Add Component". Reflection-cached.
    /// Excludes Transform (mandatory) and abstract / no-default-ctor types.
    /// </summary>
    private static readonly Type[] s_addableComponentTypes =
        typeof(Component).Assembly.GetTypes()
            .Where(t => !t.IsAbstract
                     && typeof(Component).IsAssignableFrom(t)
                     && t != typeof(Transform)
                     && t.GetConstructor(Type.EmptyTypes) != null)
            .OrderBy(t => t.Name)
            .ToArray();

    /// <summary>Render every editor window. Call after ImGui.NewFrame and ImGuizmo.BeginFrame.</summary>
    public static void Render(Scene scene, Camera? camera, Vector2i windowSize)
    {
        DrawToolbar();
        DrawHierarchy(scene);
        DrawInspector();
        DrawGizmo(camera, windowSize);
        DrawStatusBar();
    }

    // ------------------------------------------------------------------------
    // Hierarchy
    // ------------------------------------------------------------------------

    private static void DrawHierarchy(Scene scene)
    {
        var io = ImGui.GetIO();
        ImGui.SetNextWindowPos(new SnVec2(0f, ToolbarHeight), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(HierarchyWidth, io.DisplaySize.Y - ToolbarHeight), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoMove | ImGuiWindowFlags.NoResize;
        if (!ImGui.Begin("Hierarchy", flags)) { ImGui.End(); return; }

        ImGui.Text($"GameObjects ({scene.GetObjects().Count})");
        ImGui.Separator();

        var objects = scene.GetObjects();
        for (int i = 0; i < objects.Count; i++)
        {
            var go = objects[i];
            bool isSelected = Selection.IsSelected(go);

            if (ImGui.Selectable($"{go.Name}##{i}", isSelected))
            {
                if (io.KeyShift)     Selection.SelectRange(go, objects);
                else if (io.KeyCtrl) Selection.Toggle(go);
                else                 Selection.Set(go);
            }
        }

        ImGui.End();
    }

    // ------------------------------------------------------------------------
    // Inspector — editable
    // ------------------------------------------------------------------------

    private static void DrawInspector()
    {
        var io = ImGui.GetIO();
        ImGui.SetNextWindowPos(new SnVec2(io.DisplaySize.X - InspectorWidth, ToolbarHeight), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(InspectorWidth, io.DisplaySize.Y - ToolbarHeight), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoMove | ImGuiWindowFlags.NoResize;
        if (!ImGui.Begin("Inspector", flags)) { ImGui.End(); return; }

        var sel = Selection.Selected;
        if (sel.Count == 0)
        {
            ImGui.TextDisabled("Nothing selected.");
            ImGui.End();
            return;
        }

        if (sel.Count > 1)
        {
            ImGui.Text($"Multiple selected ({sel.Count})");
            ImGui.Separator();
            foreach (var go in sel) ImGui.BulletText(go.Name);
            ImGui.End();
            return;
        }

        // Single-selection details.
        var target = sel[0];
        ImGui.Text(target.Name);
        ImGui.Separator();

        // Iterate components. Track to remove (avoid mutating during iteration).
        List<Component>? toRemove = null;
        int idx = 0;
        foreach (var c in target.Components.ToArray())
        {
            string name = c.GetType().Name;

            // Remove (X) button — skip Transform.
            if (c is not Transform)
            {
                if (ImGui.SmallButton($"X##rem{idx}"))
                {
                    toRemove ??= new();
                    toRemove.Add(c);
                }
                ImGui.SameLine();
            }

            if (ImGui.CollapsingHeader($"{name}##cmp{idx}", ImGuiTreeNodeFlags.DefaultOpen))
            {
                ImGui.PushID(idx);
                ComponentInspector.Draw(c);
                ImGui.PopID();
            }

            idx++;
        }

        if (toRemove != null)
            foreach (var c in toRemove) target.RemoveComponent(c);

        // Add Component dropdown.
        ImGui.Separator();
        ImGui.SetNextItemWidth(-1);
        if (ImGui.BeginCombo("##AddComp", "Add Component..."))
        {
            foreach (var t in s_addableComponentTypes)
            {
                if (ImGui.Selectable(t.Name))
                {
                    var addMethod = typeof(GameObject)
                        .GetMethods()
                        .First(m => m.Name == "AddComponent"
                                 && m.IsGenericMethodDefinition
                                 && m.GetParameters().Length == 0)
                        .MakeGenericMethod(t);
                    addMethod.Invoke(target, null);
                }
            }
            ImGui.EndCombo();
        }

        ImGui.End();
    }

    // ------------------------------------------------------------------------
    // Toolbar — gizmo mode + space
    // ------------------------------------------------------------------------

    private static void DrawToolbar()
    {
        var io = ImGui.GetIO();
        ImGui.SetNextWindowPos(new SnVec2(0f, 0f), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(io.DisplaySize.X, ToolbarHeight), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoTitleBar
                  | ImGuiWindowFlags.NoResize
                  | ImGuiWindowFlags.NoMove
                  | ImGuiWindowFlags.NoScrollbar
                  | ImGuiWindowFlags.NoSavedSettings
                  | ImGuiWindowFlags.NoDecoration;

        if (!ImGui.Begin("##toolbar", flags)) { ImGui.End(); return; }

        ToolbarToggle("Translate (W)", EditorState.GizmoMode == GizmoMode.Translate, () => EditorState.GizmoMode = GizmoMode.Translate);
        ImGui.SameLine();
        ToolbarToggle("Rotate (E)",    EditorState.GizmoMode == GizmoMode.Rotate,    () => EditorState.GizmoMode = GizmoMode.Rotate);
        ImGui.SameLine();
        ToolbarToggle("Scale (R)",     EditorState.GizmoMode == GizmoMode.Scale,     () => EditorState.GizmoMode = GizmoMode.Scale);

        ImGui.SameLine();
        ImGui.Text("  |  ");
        ImGui.SameLine();

        string spaceLabel = EditorState.GizmoSpace == GizmoSpace.World ? "World (G)" : "Local (G)";
        if (ImGui.Button(spaceLabel))
            EditorState.GizmoSpace = EditorState.GizmoSpace == GizmoSpace.World ? GizmoSpace.Local : GizmoSpace.World;

        ImGui.End();
    }

    private static void ToolbarToggle(string label, bool active, Action onClick)
    {
        if (active)
        {
            // Highlight when active.
            ImGui.PushStyleColor(ImGuiCol.Button, new System.Numerics.Vector4(0.30f, 0.55f, 0.95f, 1f));
            if (ImGui.Button(label)) onClick();
            ImGui.PopStyleColor();
        }
        else
        {
            if (ImGui.Button(label)) onClick();
        }
    }

    // ------------------------------------------------------------------------
    // Gizmo (ImGuizmo)
    // ------------------------------------------------------------------------

    private static void DrawGizmo(Camera? camera, Vector2i windowSize)
    {
        if (camera == null) return;
        if (Selection.Selected.Count == 0) return;

        var target = Selection.Selected[0];
        // Don't gizmo the camera itself — that's confusing.
        if (target.GetComponent<Camera>() != null) return;

        // Wrap the gizmo in a fullscreen invisible window so ImGuizmo has a draw list.
        // NoMouseInputs lets clicks fall through to the gizmo handles + viewport.
        var io = ImGui.GetIO();
        ImGui.SetNextWindowPos(new SnVec2(0f, 0f), ImGuiCond.Always);
        ImGui.SetNextWindowSize(io.DisplaySize, ImGuiCond.Always);
        var overlayFlags = ImGuiWindowFlags.NoTitleBar
                         | ImGuiWindowFlags.NoResize
                         | ImGuiWindowFlags.NoMove
                         | ImGuiWindowFlags.NoScrollbar
                         | ImGuiWindowFlags.NoBackground
                         | ImGuiWindowFlags.NoSavedSettings
                         | ImGuiWindowFlags.NoBringToFrontOnFocus
                         | ImGuiWindowFlags.NoFocusOnAppearing
                         | ImGuiWindowFlags.NoNav
                         | ImGuiWindowFlags.NoMouseInputs;
        ImGui.Begin("##gizmo_overlay", overlayFlags);

        ImGuizmo.SetOrthographic(false);
        ImGuizmo.SetDrawlist();
        ImGuizmo.SetRect(0f, 0f, windowSize.X, windowSize.Y);

        // ImGuizmo wants column-major float[16] matrices. OpenTK's Matrix4 stores rows
        // contiguously; transposing converts to column-major.
        float[] view = ToColumnMajor(camera.GetViewMatrix());
        float aspect = windowSize.X / (float)windowSize.Y;
        float[] proj = ToColumnMajor(camera.GetProjectionMatrix(aspect));
        float[] model = ToColumnMajor(target.Transform.GetWorldModelMatrix());

        ImGuizmoOperation op = EditorState.GizmoMode switch
        {
            GizmoMode.Translate => ImGuizmoOperation.Translate,
            GizmoMode.Rotate    => ImGuizmoOperation.Rotate,
            GizmoMode.Scale     => ImGuizmoOperation.Scale,
            _                   => ImGuizmoOperation.Translate,
        };

        ImGuizmoMode mode = EditorState.GizmoSpace == GizmoSpace.World
            ? ImGuizmoMode.World
            : ImGuizmoMode.Local;

        if (ImGuizmo.Manipulate(ref view[0], ref proj[0], op, mode, ref model[0]))
        {
            // Decompose back to TRS and write to Transform.
            // (Caveat: writes world-space TRS into the local Transform — fine for our
            //  flat-hierarchy demo objects; would need parent-inverse math for nested trees.)
            float[] outT = new float[3];
            float[] outR = new float[3];
            float[] outS = new float[3];
            ImGuizmo.DecomposeMatrixToComponents(ref model[0], ref outT[0], ref outR[0], ref outS[0]);

            target.Transform.Position = new Vector3(outT[0], outT[1], outT[2]);
            target.Transform.Rotation = new Vector3(outR[0], outR[1], outR[2]);
            target.Transform.Scale    = new Vector3(outS[0], outS[1], outS[2]);
        }

        ImGui.End();
    }

    private static float[] ToColumnMajor(Matrix4 m)
    {
        // OpenTK Matrix4 layout: Row0..Row3 with .X .Y .Z .W. We want column-major float[16].
        return new float[]
        {
            m.M11, m.M12, m.M13, m.M14,
            m.M21, m.M22, m.M23, m.M24,
            m.M31, m.M32, m.M33, m.M34,
            m.M41, m.M42, m.M43, m.M44,
        };
    }

    // ------------------------------------------------------------------------
    // Status bar
    // ------------------------------------------------------------------------

    private static void DrawStatusBar()
    {
        var io = ImGui.GetIO();
        const float w = 320f;
        ImGui.SetNextWindowPos(new SnVec2((io.DisplaySize.X - w) * 0.5f, io.DisplaySize.Y - StatusHeight - 8f), ImGuiCond.Always);
        ImGui.SetNextWindowSize(new SnVec2(w, StatusHeight), ImGuiCond.Always);

        var flags = ImGuiWindowFlags.NoTitleBar
                  | ImGuiWindowFlags.NoResize
                  | ImGuiWindowFlags.NoMove
                  | ImGuiWindowFlags.NoScrollbar
                  | ImGuiWindowFlags.NoSavedSettings
                  | ImGuiWindowFlags.NoBringToFrontOnFocus
                  | ImGuiWindowFlags.NoFocusOnAppearing;

        ImGui.SetNextWindowBgAlpha(0.6f);
        if (ImGui.Begin("##status", flags))
        {
            string mode = EditorState.IsPlayMode ? "PLAY" : "EDIT";
            ImGui.Text($"Mode: {mode}    [F1 toggle]    W/E/R: gizmo   G: space");
        }
        ImGui.End();
    }
}

﻿using Hexa.NET.ImGui;
using Hexa.NET.ImGuizmo;

using OpenTK.Windowing.Common;
using OpenTK.Windowing.Desktop;
using OpenTK.Windowing.GraphicsLibraryFramework;

using ArcEngine.Engine.Editor;
using ArcEngine.Engine.Input;
using ArcEngine.Engine.Rendering;
using ArcEngine.Engine.SandboxGame;

namespace ArcEngine.Engine.Core;

public class Game : GameWindow
{
    private Renderer _renderer = null!;
    private Scene _scene = null!;
    private InputManager _input = null!;
    private ImGuiController _imgui = null!;

    public Game(GameWindowSettings gws, NativeWindowSettings nws)
        : base(gws, nws)
    {
    }

    protected override void OnLoad()
    {
        base.OnLoad();

        // Default to Edit mode: cursor visible.
        CursorState = CursorState.Normal;

        _renderer = new Renderer();
        _renderer.Init();

        _scene = new Scene();
        _input = new InputManager();
        _imgui = new ImGuiController(this);

        EditorState.PlayModeChanged += isPlay =>
        {
            CursorState = isPlay ? CursorState.Grabbed : CursorState.Normal;
        };

        var shader = ArcEngine.Engine.Resources.Resources.LoadShader(
            "Assets/Shaders/basic.vert",
            "Assets/Shaders/basic.frag");

        new SandboxScene().Build(_scene, shader, _input);
    }

    protected override void OnUpdateFrame(FrameEventArgs args)
    {
        base.OnUpdateFrame(args);

        float deltaTime = (float)args.Time;

        _input.Update(KeyboardState, MouseState);

        // Editor hotkeys — only in Edit mode and only when ImGui isn't capturing keyboard.
        var io = ImGui.GetIO();
        bool kbAllowed = !io.WantCaptureKeyboard;
        if (kbAllowed)
        {
            // F1: toggle Edit / Play mode.
            if (_input.WasKeyPressedThisFrame(Keys.F1))
                EditorState.IsPlayMode = !EditorState.IsPlayMode;

            if (!EditorState.IsPlayMode)
            {
                if (_input.WasKeyPressedThisFrame(Keys.W)) EditorState.GizmoMode = GizmoMode.Translate;
                if (_input.WasKeyPressedThisFrame(Keys.E)) EditorState.GizmoMode = GizmoMode.Rotate;
                if (_input.WasKeyPressedThisFrame(Keys.R)) EditorState.GizmoMode = GizmoMode.Scale;
                if (_input.WasKeyPressedThisFrame(Keys.G))
                    EditorState.GizmoSpace = EditorState.GizmoSpace == GizmoSpace.World
                        ? GizmoSpace.Local : GizmoSpace.World;
            }
        }

        _scene.Update(deltaTime);
    }

    protected override void OnRenderFrame(FrameEventArgs args)
    {
        base.OnRenderFrame(args);

        // 1) 3D scene — use the physical framebuffer size for correct viewport on hi-DPI displays.
        _renderer.RenderScene(_scene, FramebufferSize);

        // 2) Editor UI overlay.
        // Mouse events arrive in logical (ClientSize) coords, GL renders at physical (FramebufferSize)
        // pixels — pass both so ImGui's DisplayFramebufferScale is set correctly.
        _imgui.NewFrame((float)args.Time, ClientSize, FramebufferSize);
        ImGuizmo.BeginFrame();

        var camera = _scene.FindComponent<Camera>();
        EditorUI.Render(_scene, camera, ClientSize);

        _imgui.Render();

        SwapBuffers();
    }

    protected override void OnUnload()
    {
        _imgui?.Dispose();
        base.OnUnload();
    }
}

﻿namespace ArcEngine.Engine.Core;

/// <summary>
/// A node in the scene. Holds a list of <see cref="Component"/> instances. Always has
/// exactly one <see cref="Transform"/>, auto-added by the constructor.
/// </summary>
public class GameObject
{
    public string Name = "GameObject";

    /// <summary>The mandatory Transform component. Set in the constructor.</summary>
    public Transform Transform { get; }

    /// <summary>The Scene this GameObject was added to, or null if unparented. Set by <see cref="Scene.Add"/>.</summary>
    public Scene? Scene { get; internal set; }

    private readonly List<Component> _components = new();

    public IReadOnlyList<Component> Components => _components;

    public GameObject()
    {
        // Auto-attach a Transform. We assign the property *before* calling AttachComponent
        // so any code that runs during attachment (currently none, but defensively) sees a
        // valid GameObject.Transform reference.
        var t = new Transform();
        Transform = t;
        AttachComponent(t);
    }

    /// <summary>Create and attach a new component of type <typeparamref name="T"/>.</summary>
    public T AddComponent<T>() where T : Component, new()
    {
        var c = new T();
        AttachComponent(c);
        return c;
    }

    /// <summary>Attach an externally-constructed component (useful when the component has a non-default ctor).</summary>
    public T AddComponent<T>(T component) where T : Component
    {
        AttachComponent(component);
        return component;
    }

    private void AttachComponent(Component c)
    {
        c.GameObject = this;
        _components.Add(c);
    }

    /// <summary>First component of type <typeparamref name="T"/> attached to this GameObject, or null.</summary>
    public T? GetComponent<T>() where T : Component
    {
        for (int i = 0; i < _components.Count; i++)
            if (_components[i] is T t) return t;
        return null;
    }

    /// <summary>All components of type <typeparamref name="T"/> attached to this GameObject.</summary>
    public IEnumerable<T> GetComponents<T>() where T : Component
    {
        for (int i = 0; i < _components.Count; i++)
            if (_components[i] is T t) yield return t;
    }

    /// <summary>
    /// Remove a component from this GameObject. Returns false if the component is the
    /// mandatory <see cref="Transform"/> (cannot be removed) or isn't attached.
    /// Calls <see cref="Component.OnDestroy"/> on success.
    /// </summary>
    public bool RemoveComponent(Component c)
    {
        if (c is Transform) return false; // every GameObject must have a Transform
        if (!_components.Remove(c)) return false;
        c.OnDestroy();
        return true;
    }
}

﻿using OpenTK.Mathematics;
using OpenTK.Windowing.Common;
using OpenTK.Windowing.Desktop;
using OpenTK.Windowing.GraphicsLibraryFramework;

namespace ArcEngine.Engine.Input;

/// <summary>
/// Per-frame input snapshot. Wraps OpenTK's <see cref="KeyboardState"/> / <see cref="MouseState"/>
/// and tracks mouse delta so callers (Camera, gameplay code, etc.) don't have to manage
/// "first move" bookkeeping themselves.
///
/// Usage:
///   _input.Update(KeyboardState, MouseState);   // once per frame, from Game.OnUpdateFrame
///   _input.IsKeyDown(Keys.W);
///   var d = _input.MouseDelta;
/// </summary>
public class InputManager
{
    private KeyboardState? _keyboard;
    private Vector2 _lastMousePos;
    private Vector2 _mouseDelta;
    private bool _firstMove = true;

    private readonly HashSet<Keys> _downLastFrame = new();
    private readonly HashSet<Keys> _downThisFrame = new();

    /// <summary>Mouse movement (in pixels) since the previous Update call. Zero on the first frame.</summary>
    public Vector2 MouseDelta => _mouseDelta;

    /// <summary>True until the very first mouse position has been recorded.</summary>
    public bool IsMouseFirstMove => _firstMove;

    /// <summary>Update the snapshot. Call once at the start of each update tick.</summary>
    public void Update(KeyboardState keyboard, MouseState mouse)
    {
        _keyboard = keyboard;

        if (_firstMove)
        {
            _lastMousePos = mouse.Position;
            _mouseDelta = Vector2.Zero;
            _firstMove = false;
        }
        else
        {
            _mouseDelta = mouse.Position - _lastMousePos;
            _lastMousePos = mouse.Position;
        }

        // Maintain edge-detection sets. Cheap because the set of keys we care about is small.
        _downLastFrame.Clear();
        foreach (var k in _downThisFrame) _downLastFrame.Add(k);
        _downThisFrame.Clear();
    }

    public bool IsKeyDown(Keys key)
    {
        if (_keyboard == null) return false;
        bool down = _keyboard.IsKeyDown(key);
        if (down) _downThisFrame.Add(key);
        return down;
    }

    /// <summary>True only on the frame the key transitions from up to down.</summary>
    public bool WasKeyPressedThisFrame(Keys key)
    {
        // Force the "this frame" set to include this key if it's down (in case caller
        // never queried IsKeyDown for it).
        bool downNow = _keyboard != null && _keyboard.IsKeyDown(key);
        if (downNow) _downThisFrame.Add(key);
        return downNow && !_downLastFrame.Contains(key);
    }

    /// <summary>Convenience: grab the cursor for FPS-style mouse-look.</summary>
    public static void LockCursor(GameWindow window)
    {
        window.CursorState = CursorState.Grabbed;
    }
}

